func findGroups(fset *token.FileSet, files []sourceFile, threshold int) []group {
    m := make(map[string]*group)
    order := 0
    add := func(key string, size int, o occ) {
        if size < threshold { return }
        g := m[key]
        if g == nil {
            order++
            g = &group{key:key, size:size, order:order}
            m[key] = g
        }
        g.occs = append(g.occs, o)
    }

    for i := range files {
        sf := &files[i]
        ast.Inspect(sf.ast, func(n ast.Node) bool {
            if n == nil { return true }
            seq := nodeSeq(n)
            if len(seq) == 0 { return true }
            key := strings.Join(seq, " ")
            add("N:"+key, len(seq), makeOcc(fset, i, sf.path, n.Pos(), n.End()))
            return true
        })
        // A limited emulation of the original suffix-based matcher: repeated
        // runs of sibling statements (most visible at tiny thresholds).  These
        // are intentionally conservative to avoid inventing many two-off partial
        // clones that the original maximal-suffix search discards.
        collectSiblingRuns(fset, i, sf.path, sf.ast, threshold, add)
    }

    var groups []group
    for _, gp := range m {
        if len(gp.occs) < 2 { continue }
        sortOccs(gp.occs)
        groups = append(groups, *gp)
    }
    groups = dedupGroups(groups)
    groups = pruneContained(groups)
    sortGroups(groups)
    return groups
}

func collectSiblingRuns(fset *token.FileSet, fileIdx int, path string, root ast.Node, threshold int, add func(string,int,occ)) {
    ast.Inspect(root, func(n ast.Node) bool {
        if n == nil { return true }
        switch x := n.(type) {
        case *ast.BlockStmt:
            collectStmtRuns(fset, fileIdx, path, x.List, threshold, add)
        case *ast.CaseClause:
            collectStmtRuns(fset, fileIdx, path, x.Body, threshold, add)
        case *ast.CommClause:
            collectStmtRuns(fset, fileIdx, path, x.Body, threshold, add)
        }
        return true
    })
}

func collectStmtRuns(fset *token.FileSet, fileIdx int, path string, list []ast.Stmt, threshold int, add func(string,int,occ)) {
    if len(list) < 2 { return }
    seqs := make([][]string, len(list))
    sizes := make([]int, len(list))
    for i, st := range list { seqs[i] = nodeSeq(st); sizes[i] = len(seqs[i]) }
    for i := 0; i < len(list); i++ {
        var buf []string
        size := 0
        for j := i; j < len(list) && j < i+6; j++ { // enough for observed statement-run clones
            buf = append(buf, seqs[j]...)
            size += sizes[j]
            if j == i { continue }
            if size >= threshold {
                key := "S:"+strings.Join(buf, " ")
                add(key, size, makeOcc(fset, fileIdx, path, list[i].Pos(), list[j].End()))
            }
        }
    }
}

func makeOcc(fset *token.FileSet, fileIdx int, path string, p, e token.Pos) occ {
    sp := fset.Position(p)
    ep := fset.Position(e)
    return occ{file:fileIdx, path:path, start:sp.Line, end:ep.Line, pos:p, endpos:e}
}

func nodeSeq(n ast.Node) []string {
    var seq []string
    ast.Inspect(n, func(x ast.Node) bool {
        if x == nil { return true }
        seq = append(seq, typeName(x))
        return true
    })
    return seq
}

func typeName(n ast.Node) string {
    t := reflect.TypeOf(n)
    if t.Kind() == reflect.Ptr { t = t.Elem() }
    return t.Name()
}

func sortOccs(osl []occ) {
    sort.SliceStable(osl, func(i, j int) bool {
        a, b := osl[i], osl[j]
        if a.path != b.path { return a.path < b.path }
        if a.start != b.start { return a.start < b.start }
        if a.end != b.end { return a.end < b.end }
        return a.pos < b.pos
    })
}

func sameOccs(a, b []occ) bool {
    if len(a) != len(b) { return false }
    for i := range a {
        if a[i].path != b[i].path || a[i].start != b[i].start || a[i].end != b[i].end || a[i].pos != b[i].pos { return false }
    }
    return true
}

func dedupGroups(in []group) []group {
    var out []group
    for _, g := range in {
        merged := false
        for i := range out {
            if sameOccs(out[i].occs, g.occs) {
                if g.size > out[i].size { out[i].size = g.size; out[i].key = g.key }
                if g.order < out[i].order { out[i].order = g.order }
                merged = true
                break
            }
        }
        if !merged { out = append(out, g) }
    }
    return out
}

func pruneContained(in []group) []group {
    keep := make([]bool, len(in))
    for i := range keep { keep[i] = true }
    for i, g := range in {
        for j, h := range in {
            if i == j || h.size <= g.size || len(h.occs) != len(g.occs) { continue }
            if allContained(g.occs, h.occs) {
                keep[i] = false
                break
            }
        }
    }
    var out []group
    for i, g := range in { if keep[i] { out = append(out, g) } }
    return out
}

func allContained(small, big []occ) bool {
    used := make([]bool, len(big))
    for _, s := range small {
        found := false
        for i, b := range big {
            if used[i] { continue }
            if s.path == b.path && s.start >= b.start && s.end <= b.end {
                used[i] = true; found = true; break
            }
        }
        if !found { return false }
    }
    return true
}

func sortGroups(gs []group) {
    sort.SliceStable(gs, func(i, j int) bool {
        a, b := gs[i], gs[j]
        // This ordering is chosen to resemble dupl's suffix-tree traversal for
        // common cases: larger syntax units are preferred when they start at an
        // earlier source position; otherwise the earliest clone occurrence wins.
        if a.occs[0].path != b.occs[0].path { return a.occs[0].path < b.occs[0].path }
        if a.occs[0].start != b.occs[0].start { return a.occs[0].start < b.occs[0].start }
        if a.size != b.size { return a.size > b.size }
        if len(a.occs) != len(b.occs) { return len(a.occs) < len(b.occs) }
        return a.order < b.order
    })
}

func printText(groups []group) {
    for _, g := range groups {
        fmt.Printf("found %d clones:\n", len(g.occs))
        for _, o := range g.occs { fmt.Printf("  %s:%d,%d\n", o.path, o.start, o.end) }
    }
    fmt.Printf("\nFound total %d clone groups.\n", len(groups))
}

func printPlumbing(groups []group) {
    for _, g := range groups {
        n := len(g.occs)
        for i, o := range g.occs {
            d := g.occs[(i+1)%n]
            fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n", o.path, o.start, o.end, d.path, d.start, d.end)
        }
    }
}

func printHTML(groups []group, files []sourceFile) {
    fmt.Print(`<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>
`)
    for i, g := range groups {
        fmt.Printf("<h1>#%d found %d clones</h1>\n", i+1, len(g.occs))
        for _, o := range g.occs {
            fmt.Printf("<h2>%s:%d</h2>\n", html.EscapeString(o.path), o.start)
            fmt.Printf("<pre>%s</pre>\n", html.EscapeString(fragment(files, o)))
        }
    }
}

func fragment(files []sourceFile, o occ) string {
    if o.file < 0 || o.file >= len(files) { return "" }
    lines := files[o.file].lines
    if len(lines) == 0 { return "" }
    s, e := o.start, o.end
    if s < 1 { s = 1 }
    if e > len(lines) { e = len(lines) }
    if s > e { return "" }
    var b bytes.Buffer
    for i := s; i <= e; i++ {
        if i > s { b.WriteByte('\n') }
        b.WriteString(lines[i-1])
    }
    return b.String()
}
EOF
